mapper.select:

SELECT 
    (SELECT 
            IFNULL(SUM((buying_price * buying_shares + CASE
                            WHEN sign_type = 0 THEN buying_fee + buying_stamp_duty
                            ELSE (buying_fee + buying_stamp_duty) * - 1
                        END) / exchange_rate),
                        0)
        FROM
            user_follow_up_trading
        WHERE
            user_id = #{userId}

            	and trading_time >= #{startTime}


            	and trading_time <= #{endTime}


            ) + (SELECT 
            IFNULL(SUM((buying_price * buying_shares + buying_fee + buying_stamp_duty) / exchange_rate),
                        0)
        FROM
            user_stock_pending
        WHERE
            user_id = #{userId} AND position_status = 2

            	and pending_time >= #{startTime}


            	and pending_time <= #{endTime}

            ) + (SELECT 
            IFNULL(SUM((amount_received / exchange_rate)),
                        0)
        FROM
            user_stock_closing_position
        WHERE
            user_id = #{userId}

            	and closing_time >= #{startTime}


            	and closing_time <= #{endTime}

            )
